Path("src/lib/nativeAppLifecycle.ts").write_text('''import { App as CapacitorApp, type AppState } from "@capacitor/app";\nimport { Capacitor } from "@capacitor/core";\n\nexport type NativeAppStateListener = (state: AppState) => void;\n\n/**\n * Native container 上だけ Capacitor App lifecycle を購読する。\n * Web では既存の visibility/pagehide/pageshow を使うため登録しない。\n *\n * addListener() は非同期なので、登録完了より先に React effect が cleanup された場合も\n * 遅れて返った handle を即 remove し、listener leak を残さない。\n */\nexport function subscribeToNativeAppState(listener: NativeAppStateListener): () => void {\n  if (!Capacitor.isNativePlatform()) return () => {};\n\n  let disposed = false;\n  let removeListener: (() => Promise<void>) | null = null;\n\n  void CapacitorApp.addListener("appStateChange", listener)\n    .then((handle) => {\n      if (disposed) {\n        void handle.remove();\n        return;\n      }\n      removeListener = () => handle.remove();\n    })\n    .catch(() => {\n      // Native plugin 登録だけが失敗しても、DOM lifecycle の保存境界は残る。\n      // ここで画面自体をエラー化するとメモ編集を妨げるため、fallback を優先する。\n    });\n\n  return () => {\n    disposed = true;\n    if (removeListener) void removeListener();\n  };\n}\n''')

Path("src/lib/__tests__/nativeAppLifecycle.test.ts").write_text('''import { beforeEach, describe, expect, it, vi } from "vitest";\n\nconst mocks = vi.hoisted(() => ({\n  isNativePlatform: vi.fn(),\n  addListener: vi.fn(),\n}));\n\nvi.mock("@capacitor/core", () => ({\n  Capacitor: { isNativePlatform: mocks.isNativePlatform },\n}));\n\nvi.mock("@capacitor/app", () => ({\n  App: { addListener: mocks.addListener },\n}));\n\nimport { subscribeToNativeAppState } from "../nativeAppLifecycle";\n\ndescribe("native app lifecycle subscription", () => {\n  beforeEach(() => {\n    mocks.isNativePlatform.mockReset();\n    mocks.addListener.mockReset();\n  });\n\n  it("webではnative listenerを登録しない", () => {\n    mocks.isNativePlatform.mockReturnValue(false);\n\n    const unsubscribe = subscribeToNativeAppState(() => {});\n    unsubscribe();\n\n    expect(mocks.addListener).not.toHaveBeenCalled();\n  });\n\n  it("nativeではappStateChangeを登録しcleanupでremoveする", async () => {\n    mocks.isNativePlatform.mockReturnValue(true);\n    const remove = vi.fn().mockResolvedValue(undefined);\n    mocks.addListener.mockResolvedValue({ remove });\n\n    const listener = vi.fn();\n    const unsubscribe = subscribeToNativeAppState(listener);\n    await Promise.resolve();\n    unsubscribe();\n    await Promise.resolve();\n\n    expect(mocks.addListener).toHaveBeenCalledWith("appStateChange", listener);\n    expect(remove).toHaveBeenCalledTimes(1);\n  });\n\n  it("登録完了前にcleanupされても遅れて返ったlistenerをremoveする", async () => {\n    mocks.isNativePlatform.mockReturnValue(true);\n    let resolveHandle: ((value: { remove: () => Promise<void> }) => void) | null = null;\n    const remove = vi.fn().mockResolvedValue(undefined);\n    mocks.addListener.mockReturnValue(\n      new Promise((resolve) => {\n        resolveHandle = resolve;\n      }),\n    );\n\n    const unsubscribe = subscribeToNativeAppState(() => {});\n    unsubscribe();\n    resolveHandle?.({ remove });\n    await Promise.resolve();\n    await Promise.resolve();\n\n    expect(remove).toHaveBeenCalledTimes(1);\n  });\n\n  it("native plugin登録失敗時もcleanup可能なままにする", async () => {\n    mocks.isNativePlatform.mockReturnValue(true);\n    mocks.addListener.mockRejectedValue(new Error("plugin unavailable"));\n\n    const unsubscribe = subscribeToNativeAppState(() => {});\n    await Promise.resolve();\n    expect(() => unsubscribe()).not.toThrow();\n  });\n});\n''')

Path("src/__tests__/App.native-lifecycle.test.tsx").write_text('''import { act } from "react";\nimport { createRoot, type Root } from "react-dom/client";\nimport { afterEach, beforeEach, describe, expect, it, vi } from "vitest";\nimport type { Note } from "../types/note";\nimport { copy } from "../lib/i18n";\nimport { STORAGE_KEY_FOR_TESTING } from "../lib/storage";\n\nconst lifecycle = vi.hoisted(() => ({\n  handler: null as ((state: { isActive: boolean }) => void) | null,\n  unsubscribe: vi.fn(),\n}));\n\nvi.mock("../lib/nativeAppLifecycle", () => ({\n  subscribeToNativeAppState: vi.fn((handler: (state: { isActive: boolean }) => void) => {\n    lifecycle.handler = handler;\n    return lifecycle.unsubscribe;\n  }),\n}));\n\nimport App from "../App";\n\n(globalThis as { IS_REACT_ACT_ENVIRONMENT?: boolean }).IS_REACT_ACT_ENVIRONMENT = true;\n\nfunction makeNote(overrides: Partial<Note> = {}): Note {\n  return {\n    id: "note-1",\n    title: "元のメモ",\n    body: "本文",\n    createdAt: "2026-08-28T00:00:00.000Z",\n    updatedAt: "2026-08-28T00:00:00.000Z",\n    isFavorite: false,\n    locale: "ja",\n    ...overrides,\n  };\n}\n\nfunction mockLocalStorage() {\n  const store: Record<string, string> = {};\n  return {\n    getItem: vi.fn((key: string) => store[key] ?? null),\n    setItem: vi.fn((key: string, value: string) => {\n      store[key] = value;\n    }),\n    removeItem: vi.fn((key: string) => {\n      delete store[key];\n    }),\n    clear: vi.fn(() => {\n      Object.keys(store).forEach((key) => delete store[key]);\n    }),\n    get _store() {\n      return store;\n    },\n  };\n}\n\nfunction click(element: Element) {\n  element.dispatchEvent(new MouseEvent("click", { bubbles: true }));\n}\n\nfunction findButton(container: HTMLElement, text: string): HTMLButtonElement {\n  const button = Array.from(container.querySelectorAll("button")).find((candidate) =>\n    candidate.textContent?.includes(text),\n  );\n  if (!(button instanceof HTMLButtonElement)) throw new Error(`Button not found: ${text}`);\n  return button;\n}\n\nfunction openEditor(container: HTMLElement) {\n  act(() => click(findButton(container, "元のメモ")));\n  act(() => click(findButton(container, copy.editNote)));\n}\n\nfunction changeTextarea(container: HTMLElement, value: string) {\n  const textarea = container.querySelector("textarea");\n  if (!(textarea instanceof HTMLTextAreaElement)) throw new Error("textarea not found");\n  const setter = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, "value")?.set;\n  setter?.call(textarea, value);\n  textarea.dispatchEvent(new Event("input", { bubbles: true }));\n}\n\ndescribe("App Capacitor native lifecycle", () => {\n  let storage: ReturnType<typeof mockLocalStorage>;\n  let container: HTMLDivElement;\n  let root: Root | null = null;\n\n  beforeEach(() => {\n    vi.useFakeTimers();\n    lifecycle.handler = null;\n    lifecycle.unsubscribe.mockReset();\n    storage = mockLocalStorage();\n    Object.defineProperty(window, "localStorage", {\n      value: storage,\n      writable: true,\n      configurable: true,\n    });\n    container = document.createElement("div");\n    document.body.appendChild(container);\n  });\n\n  afterEach(() => {\n    if (root) act(() => root?.unmount());\n    container.remove();\n    vi.useRealTimers();\n  });\n\n  function renderApp() {\n    root = createRoot(container);\n    act(() => root?.render(<App />));\n    if (!lifecycle.handler) throw new Error("native lifecycle listener was not registered");\n  }\n\n  it("native inactiveで500ms debounceを待たずdirtyメモをflushする", () => {\n    storage._store[STORAGE_KEY_FOR_TESTING] = JSON.stringify([makeNote()]);\n    renderApp();\n    openEditor(container);\n    changeTextarea(container, "native background直前の本文");\n\n    const before = JSON.parse(storage._store[STORAGE_KEY_FOR_TESTING]) as Note[];\n    expect(before[0].body).toBe("本文");\n\n    act(() => lifecycle.handler?.({ isActive: false }));\n\n    const saved = JSON.parse(storage._store[STORAGE_KEY_FOR_TESTING]) as Note[];\n    expect(saved[0].body).toBe("native background直前の本文");\n  });\n\n  it("native active復帰時、ローカルがcleanなら取りこぼした保存先変更を再読込する", () => {\n    storage._store[STORAGE_KEY_FOR_TESTING] = JSON.stringify([makeNote()]);\n    renderApp();\n\n    storage._store[STORAGE_KEY_FOR_TESTING] = JSON.stringify([\n      makeNote({ title: "復帰時の外部最新版", updatedAt: "2026-08-28T00:01:00.000Z" }),\n    ]);\n\n    act(() => lifecycle.handler?.({ isActive: true }));\n\n    expect(container.textContent).toContain("復帰時の外部最新版");\n    expect(container.textContent).not.toContain("元のメモ");\n  });\n\n  it("native active時にdirtyなら外部版を勝手に採用せず、次のinactive保存で競合保護する", () => {\n    storage._store[STORAGE_KEY_FOR_TESTING] = JSON.stringify([makeNote()]);\n    renderApp();\n    openEditor(container);\n    changeTextarea(container, "端末内の未保存編集");\n\n    const remote = [\n      makeNote({\n        title: "別画面の最新版",\n        body: "remote",\n        updatedAt: "2026-08-28T00:02:00.000Z",\n      }),\n    ];\n    storage._store[STORAGE_KEY_FOR_TESTING] = JSON.stringify(remote);\n\n    act(() => lifecycle.handler?.({ isActive: true }));\n    const textarea = container.querySelector("textarea");\n    expect(textarea?.value).toBe("端末内の未保存編集");\n\n    act(() => lifecycle.handler?.({ isActive: false }));\n\n    expect(JSON.parse(storage._store[STORAGE_KEY_FOR_TESTING]) as Note[]).toEqual(remote);\n    expect(container.textContent).toContain(copy.storageConflictTitle);\n  });\n\n  it("unmount時にnative listenerを解除する", () => {\n    storage._store[STORAGE_KEY_FOR_TESTING] = JSON.stringify([makeNote()]);\n    renderApp();\n\n    act(() => root?.unmount());\n    root = null;\n\n    expect(lifecycle.unsubscribe).toHaveBeenCalledTimes(1);\n  });\n});\n''')

